```javascript
// scripts.js
let currentUser = null;
let players = [];

function registerUser() {
    const username = document.getElementById('username').value;
    const password = document.getElementById('password').value;
    // Save user to local storage or server
    localStorage.setItem(username, password);
    alert('Registration successful!');
    showLoginPage();
}

function loginUser() {
    const username = document.getElementById('login-username').value;
    const password = document.getElementById('login-password').value;
    const storedPassword = localStorage.getItem(username);
    if (storedPassword === password) {
        currentUser = username;
        alert('Login successful!');
        showPairUpPage();
    } else {
        alert('Invalid credentials!');
    }
}

function showLoginPage() {
    document.getElementById('registration').style.display = 'none';
    document.getElementById('login').style.display = 'block';
    document.getElementById('game-description').style.display = 'none';
    document.getElementById('pair-up').style.display = 'none';
}

function showPairUpPage() {
    document.getElementById('login').style.display = 'none';
    document.getElementById('game-description').style.display = 'block';
    document.getElementById('pair-up').style.display = 'block';
}

function joinRoom() {
    const roomId = document.getElementById('room-id').value;
    // Logic to join the room
    alert(`Joined room ${roomId}`);
    startGame();
}

function randomMatch() {
    // Logic for random match making
    alert('Random match started');
    startGame();
}

function startGame() {
    document.getElementById('front-page').classList.remove('active');
    document.getElementById('game-play').classList.add('active');
    // Start the game logic
}

function showGameOverPage(timeUsed, player1Stats, player2Stats) {
    document.getElementById('game-play').classList.remove('active');
    document.getElementById('game-over').classList.add('active');

    document.getElementById('time-used').innerText = timeUsed;
    document.getElementById('player1-score').innerText = player1Stats.score;
    document.getElementById('player1-health').innerText = player1Stats.health;
    document.getElementById('player1-hits').innerText = player1Stats.hits;
    document.getElementById('player1-opponent-hits').innerText = player1Stats.opponentHits;
    document.getElementById('player1-mushrooms').innerText = player1Stats.mushrooms;
    document.getElementById('player1-hearts').innerText = player1Stats.hearts;

    document.getElementById('player2-score').innerText = player2Stats.score;
    document.getElementById('player2-health').innerText = player2Stats.health;
    document.getElementById('player2-hits').innerText = player2Stats.hits;
    document.getElementById('player2-opponent-hits').innerText = player2Stats.opponentHits;
    document.getElementById('player2-mushrooms').innerText = player2Stats.mushrooms;
    document.getElementById('player2-hearts').innerText = player2Stats.hearts;

    drawHexbinChart(player1Stats, player2Stats);
}

function playAgain() {
    // Reset game state
    startGame();
}

function returnToFrontPage() {
    document.getElementById('game-over').classList.remove('active');
    document.getElementById('front-page').classList.add('active');
    // Reset user session
    currentUser = null;
}

function drawHexbinChart(player1Stats, player2Stats) {
    const ctx = document.getElementById('hexbin-chart').getContext('2d');
    const data = {
        datasets: [{
            label: 'Player Statistics',
            data: [
                { x: player1Stats.score, y: player1Stats.health },
                { x: player2Stats.score, y: player2Stats.health }
            ],
            backgroundColor: ['rgba(75, 192, 192, 0.2)', 'rgba(153, 102, 255, 0.2)'],
            borderColor: ['rgba(75, 192, 192, 1)', 'rgba(153, 102, 255, 1)'],
            borderWidth: 1
        }]
    };

    const options = {
        scales: {
            xAxes: [{
                type: 'linear',
                position: 'bottom'
            }],
            yAxes: [{
                type: 'linear'
            }]
        }
    };

    new Chart(ctx, {
        type: 'scatter',
        data: data,
        options: options
    });
}

// Check if user is logged in
window.onload = function() {
    if (localStorage.getItem(currentUser)) {
        showPairUpPage();
    } else {
        showLoginPage();
    }
};
```

